// Failure effects have independent expiry times and are removed on every restart.
const beforeCursesStop=stopLoops,beforeCursesFinish=finishTrial,beforeCursesRender=render,beforeCursesSwap=swap,beforeCursesVenom=launchPoison;
let curses=new Map(),curseInterval=null;
const curseDefs={
 meteor:{name:'Quemadura',duration:12000,color:'#ff9e72',description:'El fuego roba 3 segundos cada 2 segundos.',path:'M32 5C15 25 40 27 20 43c-5-6-6-12-6-12C1 54 24 66 41 57c17-11 4-26-3-32 3 12-4 15-7 10-5-8 7-14 1-30Z'},
 memory:{name:'Confusión',duration:8000,color:'#b3b9ff',description:'La niebla difumina el código durante 8 segundos.',path:'M12 22c0-11 16-16 22-8 13-8 26 7 16 16 12 8 1 24-12 19-7 10-24 7-22-6-14-2-16-17-4-21Zm14-5v32m13-30v30M19 29h25M21 39h23'},
 dial:{name:'Congelación',duration:8000,color:'#85e4ff',description:'Una pieza queda congelada durante 8 segundos.',path:'M32 5v54M9 18l46 28M9 46l46-28M24 10l8 8 8-8M24 54l8-8 8 8M10 27l10-2-1-10M45 49l-1-10 10-2M10 37l10 2-1 10M45 15l-1 10 10 2'},
 keys:{name:'Tiempo maldito',duration:10000,color:'#eccf83',description:'El reloj corre al doble durante 10 segundos de efecto.',path:'M16 7h32M16 57h32M20 7c0 14 6 17 12 25-6 8-12 11-12 25m24-50c0 14-6 17-12 25 6 8 12 11 12 25M25 18h14M25 49h14'}
};
function curseSvg(kind){const d=curseDefs[kind];return '<svg viewBox="0 0 64 64" aria-hidden="true"><path d="'+d.path+'" fill="'+(kind==='meteor'?'currentColor':'none')+'" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
stopLoops=function(){beforeCursesStop();clearInterval(curseInterval);curseInterval=null;curses.clear();document.getElementById('curseRack')?.remove();document.querySelector('main').classList.remove('confused-code');document.querySelectorAll('.curse-damage').forEach(n=>n.remove())};
launchPoison=function(duration){beforeCursesVenom(duration);if($('poisonTime')){$('poisonTime').hidden=false;$('poisonButton').setAttribute('aria-expanded','true')}};
function applyCurse(kind){if(!session||!curseDefs[kind])return;const now=performance.now(),d=curseDefs[kind],old=curses.get(kind);if(old){old.ends=Math.max(now,old.ends)+d.duration;return}const frozenPiece=kind==='dial'?states[current].order[Math.floor(Math.random()*states[current].order.length)]:null;curses.set(kind,{kind,ends:now+d.duration,nextTick:now+2000,last:now,frozenPiece});ensureCurseRack();if(!curseInterval)curseInterval=setInterval(curseTick,50);updateCurseUI()}
function ensureCurseRack(){if($('curseRack'))return;const rack=document.createElement('aside');rack.id='curseRack';rack.className='curse-rack';rack.setAttribute('aria-label','Efectos activos');document.body.append(rack)}
function curseTick(){if(!session||['lost','won'].includes(session.phase)){clearCurses();return}const now=performance.now();for(const [kind,c] of curses){if(kind==='meteor'){while(c.nextTick<=now&&c.nextTick<c.ends){c.nextTick+=2000;session.remaining=Math.max(0,session.remaining-3000);curseDamage('−3',kind)}}if(kind==='keys'&&session.phase==='puzzle'){const elapsed=Math.max(0,Math.min(now,c.ends)-c.last);session.remaining=Math.max(0,session.remaining-elapsed)}c.last=now;if(now>=c.ends)curses.delete(kind);if(session.remaining<=0){endAdventure('El hechizo apagó el reloj','El pergamino se ha cerrado. Inténtalo otra vez.');return}}updateHud();updateCurseUI();if(!curses.size){clearInterval(curseInterval);curseInterval=null}}
function curseDamage(text,kind){const r=$('clock').getBoundingClientRect(),n=document.createElement('span');n.className='curse-damage';n.textContent=text;n.style.color=curseDefs[kind].color;n.style.left=(r.left+r.width/2)+'px';n.style.top=r.bottom+'px';document.body.append(n);later(()=>n.remove(),1100)}
function updateCurseUI(){const rack=$('curseRack');if(rack){for(const [kind,c] of curses){let card=document.getElementById('curse-'+kind);const d=curseDefs[kind];if(!card){card=document.createElement('div');card.id='curse-'+kind;card.className='curse-card';card.style.setProperty('--curse-color',d.color);card.innerHTML='<button aria-label="Consultar '+d.name+'" aria-expanded="false">'+curseSvg(kind)+'<span>'+d.name+'<b class="curse-seconds"></b></span></button><p hidden>'+d.description+'</p>';rack.append(card);card.querySelector('button').onclick=()=>{const p=card.querySelector('p');p.hidden=!p.hidden;card.querySelector('button').setAttribute('aria-expanded',String(!p.hidden))}}card.querySelector('.curse-seconds').textContent=Math.max(0,Math.ceil((c.ends-performance.now())/1000))+' s'}rack.querySelectorAll('.curse-card').forEach(card=>{if(!curses.has(card.id.replace('curse-','')))card.remove()})}document.querySelector('main').classList.toggle('confused-code',curses.has('memory'));const ice=curses.get('dial');document.querySelectorAll('.piece').forEach(b=>{const frozen=!!ice&&states[current].order[Number(b.dataset.index)]===ice.frozenPiece;b.classList.toggle('frozen-piece',frozen);b.disabled=frozen;b.setAttribute('aria-disabled',String(frozen))});$('clock')?.classList.toggle('cursed-clock',curses.has('keys'))}
function clearCurses(){clearInterval(curseInterval);curseInterval=null;curses.clear();document.getElementById('curseRack')?.remove();updateCurseUI()}
render=function(){beforeCursesRender();updateCurseUI()};
swap=function(a,b){const ice=curses.get('dial'),order=states[current].order;if(ice&&(order[a]===ice.frozenPiece||order[b]===ice.frozenPiece)){if($('feedback'))$('feedback').textContent='Esa pieza está congelada: '+Math.ceil((ice.ends-performance.now())/1000)+' s.';return}beforeCursesSwap(a,b)};
finishTrial=function(pista,heal,hits){if(!session||!trial)return;const kind=trial.kind;if(!heal&&session.hearts>1&&curseDefs[kind])applyCurse(kind);beforeCursesFinish(pista,heal,hits)};
failureFlash=function(kind,callback){const colors={icons:'#b577ec',meteor:'#f39b67',memory:'#a2acf4',dial:'#80daf4',keys:'#dfc777'};const names={icons:'¡Estás envenenado!',meteor:'¡Te estás quemando!',memory:'¡Estás confundido!',dial:'¡Una pieza se congeló!',keys:'¡El tiempo está maldito!'};document.body.classList.add(kind==='icons'?'venom-wash':'failure-wash');showOverlay('<div class="failure-scene"><h2 style="color:'+colors[kind]+'">'+names[kind]+'</h2><div class="failure-particles" aria-hidden="true">'+Array.from({length:18},(_,i)=>'<span style="color:'+colors[kind]+';--a:'+i*20+'deg;--d:'+(60+Math.random()*140)+'px">✦</span>').join('')+'</div></div>');const overlay=$('challengeOverlay');overlay.style.background=kind==='icons'?'#511277ce':kind==='dial'?'#124358ce':kind==='memory'?'#24234bce':kind==='keys'?'#493d18ce':'#592a19ce';overlay.querySelector('.challenge').classList.add('flash-card');later(()=>{document.body.classList.remove('venom-wash','failure-wash');callback()},2000)};
